"""Find the earliest Friday the 13th and count them in a 400-year cycle (proleptic Gregorian)."""

from datetime import date, timedelta

# --- Earliest Friday the 13th starting from 0001-01-01 ---
d = date(1, 1, 13)  # start checking the 13th of each month
while True:
    if d.weekday() == 4:  # Friday
        print(f"Earliest Friday the 13th: {d} ({d.strftime('%A, %B %d, %Y')})")
        break
    # jump to the 13th of the next month
    if d.month == 12:
        d = date(d.year + 1, 1, 13)
    else:
        d = date(d.year, d.month + 1, 13)

# --- Count Friday the 13ths in a full 400-year cycle (years 1–400) ---
count = 0
for y in range(1, 401):
    for m in range(1, 13):
        if date(y, m, 13).weekday() == 4:
            count += 1

print(f"\nFriday the 13ths in a 400-year cycle: {count}")
print(f"Average per year: {count / 400:.4f}")

# --- Bonus: distribution by month ---
